{"command":"cat > bench_gcm.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/modes.h>

static double now() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec * 1e-9;
}

static void bench_evp(const unsigned char *key, const unsigned char *nonce,
                      const unsigned char *pt, size_t n,
                      const unsigned char *aad, size_t aad_len, int reps) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *out = malloc(n + 32);
    unsigned char tag[16];
    int outlen = 0, total = 0;
    /* warmup */
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    if (aad_len) EVP_EncryptUpdate(ctx, NULL, &outlen, aad, (int)aad_len);
    EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
    total = outlen;
    EVP_EncryptFinal_ex(ctx, out + total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    double t0 = now();
    for (int i = 0; i < reps; i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL); /* reset? */
        /* full reinit */
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        if (aad_len) EVP_EncryptUpdate(ctx, NULL, &outlen, aad, (int)aad_len);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out + total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("EVP aes-128-gcm: %.4f s/call  %.1f MB/s\n", (t1-t0)/reps, (reps * (n/1e6)) / (t1-t0));
    free(out);
    EVP_CIPHER_CTX_free(ctx);
}

/* Try calling aesni_ctr32 via CRYPTO_ctr128? We don't have aesni symbol in headers.
   Use CRYPTO_gcm128 with AES_encrypt block function. */
static void bench_gcm128(const unsigned char *key, const unsigned char *nonce,
                         const unsigned char *pt, size_t n,
                         const unsigned char *aad, size_t aad_len, int reps) {
    AES_KEY aes;
    AES_set_encrypt_key(key, 128, &aes);
    GCM128_CONTEXT *g = CRYPTO_gcm128_new(&aes, (block128_f)AES_encrypt);
    unsigned char *out = malloc(n + 32);
    unsigned char tag[16];

    CRYPTO_gcm128_setiv(g, nonce, 12);
    if (aad_len) CRYPTO_gcm128_aad(g, aad, aad_len);
    CRYPTO_gcm128_encrypt(g, pt, out, n);
    CRYPTO_gcm128_tag(g, tag, 16);

    double t0 = now();
    for (int i = 0; i < reps; i++) {
        /* re-init context each time to be fair (new nonce/key path) */
        CRYPTO_gcm128_setiv(g, nonce, 12);
        if (aad_len) CRYPTO_gcm128_aad(g, aad, aad_len);
        CRYPTO_gcm128_encrypt(g, pt, out, n);
        CRYPTO_gcm128_tag(g, tag, 16);
    }
    double t1 = now();
    printf("CRYPTO_gcm128_encrypt (AES_encrypt block): %.4f s/call  %.1f MB/s\n",
           (t1-t0)/reps, (reps * (n/1e6)) / (t1-t0));

    /* encrypt_ctr32 with NULL stream falls back? signature requires stream. skip */
    free(out);
    CRYPTO_gcm128_release(g);
}

int main() {
    size_t n = 60 * 1024 * 1024;
    unsigned char *pt = malloc(n);
    unsigned char key[16], nonce[12], aad[32];
    FILE *f = fopen("/dev/urandom", "rb");
    fread(pt, 1, n, f); fread(key, 1, 16, f); fread(nonce, 1, 12, f); fread(aad, 1, 32, f);
    fclose(f);
    int reps = 3;
    bench_evp(key, nonce, pt, n, aad, 32, reps);
    bench_gcm128(key, nonce, pt, n, aad, 32, reps);
    free(pt);
    return 0;
}
