{"command":"cat > aesgcm_ext.c << 'EOF'
#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <openssl/evp.h>

static PyObject *encrypt(PyObject *self, PyObject *args) {
    Py_buffer key, nonce, pt, aad;
    int has_aad;
    if (!PyArg_ParseTuple(args, "y*y*y*y*", &key, &nonce, &pt, &aad))
        return NULL;

    const EVP_CIPHER *cipher = NULL;
    if (key.len == 16) cipher = EVP_aes_128_gcm();
    else if (key.len == 24) cipher = EVP_aes_192_gcm();
    else if (key.len == 32) cipher = EVP_aes_256_gcm();
    else {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        PyErr_SetString(PyExc_ValueError, "bad key size");
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        return PyErr_NoMemory();
    }

    PyObject *ct = PyBytes_FromStringAndSize(NULL, pt.len);
    PyObject *tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) {
        Py_XDECREF(ct); Py_XDECREF(tag);
        EVP_CIPHER_CTX_free(ctx);
        PyBuffer_Release(&key); PyBuffer_Release(&nonce);
        PyBuffer_Release(&pt); PyBuffer_Release(&aad);
        return PyErr_NoMemory();
    }

    int ok = 1;
    int outlen = 0;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)nonce.len, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, (unsigned char *)key.buf, (unsigned char *)nonce.buf) != 1) ok = 0;
    if (ok && aad.len > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outlen, (unsigned char *)aad.buf, (int)aad.len) != 1) ok = 0;
    }
    if (ok && pt.len > 0) {
        /* EVP_EncryptUpdate takes int length. Chunk if needed. */
        size_t done = 0;
        unsigned char *outp = (unsigned char *)PyBytes_AS_STRING(ct);
        unsigned char *inp = (unsigned char *)pt.buf;
        while (done < (size_t)pt.len) {
            size_t chunk = (size_t)pt.len - done;
            if (chunk > 1 << 30) chunk = 1 << 30;
            int ol = 0;
            if (EVP_EncryptUpdate(ctx, outp + done, &ol, inp + done, (int)chunk) != 1) { ok = 0; break; }
            done += (size_t)ol;
        }
    }
    if (ok) {
        unsigned char tmp[16];
        int fl = 0;
        if (EVP_EncryptFinal_ex(ctx, tmp, &fl) != 1) ok = 0;
        if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, (unsigned char *)PyBytes_AS_STRING(tag)) != 1) ok = 0;
    }

    EVP_CIPHER_CTX_free(ctx);
    PyBuffer_Release(&key); PyBuffer_Release(&nonce);
    PyBuffer_Release(&pt); PyBuffer_Release(&aad);

    if (!ok) {
        Py_DECREF(ct); Py_DECREF(tag);
        PyErr_SetString(PyExc_RuntimeError, "EVP encrypt failed");
        return NULL;
    }
    return Py_BuildValue("NN", ct, tag);
}

static PyMethodDef methods[] = {
    {"encrypt", encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "aesgcm_ext", NULL, -1, methods
};
PyMODINIT_FUNC PyInit_aesgcm_ext(void) { return PyModule_Create(&moduledef); }
