        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("full reinit: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* reuse ctx, only re-set key/iv via EncryptInit with NULL cipher */
    t0 = now();
    for (int i=0;i<reps;i++) {
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("reuse ctx reinit key/iv: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* no aad */
    t0 = now();
    for (int i=0;i<reps;i++) {
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, out, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, out+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("no aad full reinit: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* malloc each time */
    t0 = now();
    for (int i=0;i<reps;i++) {
        unsigned char *o = malloc(n);
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, o, &outlen, pt, (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, o+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        free(o);
    }
    t1 = now();
    printf("malloc each: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* touch output (simulate copy) */
    t0 = now();
    for (int i=0;i<reps;i++) {
        volatile unsigned char s = 0;
        for (size_t j=0;j<n;j+=64) s += out[j];
        (void)s;
    }
    t1 = now();
    printf("touch out stride64: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* memcpy */
    unsigned char *dst = malloc(n);
    t0 = now();
    for (int i=0;i<reps;i++) memcpy(dst, out, n);
    t1 = now();
    printf("memcpy: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    free(pt); free(out); free(dst);
    return 0;
}
