#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/evp.h>

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 60ull*1024*1024;
    int reps = 5;
    unsigned char key[16], nonce[12], aad[32], tag[16];
    FILE *f = fopen("/dev/urandom","rb");
    fread(key,1,16,f); fread(nonce,1,12,f); fread(aad,1,32,f);

    /* prealloc many buffers so each rep uses fresh pages */
    unsigned char **pts = malloc(sizeof(void*)*reps);
    unsigned char **outs = malloc(sizeof(void*)*reps);
    for (int i=0;i<reps;i++) {
        pts[i] = malloc(n);
        outs[i] = malloc(n+32);
        fread(pts[i], 1, n, f); /* fill so pages are resident and dirty */
        memset(outs[i], 0, 4096); /* touch first page */
    }
    fclose(f);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int outlen, total;

    /* warmup on extra */
    unsigned char *wpt = malloc(n), *wout = malloc(n);
    memset(wpt, 1, n);
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, wout, &outlen, wpt, (int)n);
    EVP_EncryptFinal_ex(ctx, wout+outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    double t0 = now();
    for (int i=0;i<reps;i++) {
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, outs[i], &outlen, pts[i], (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, outs[i]+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    double t1 = now();
    printf("fresh buffers pre-faulted: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* reuse same buffer */
    t0 = now();
    for (int i=0;i<reps;i++) {
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, outs[0], &outlen, pts[0], (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, outs[0]+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    t1 = now();
    printf("reused buffer: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* malloc inside timed region, not prefaulted (demand zero + encrypt) */
    t0 = now();
    for (int i=0;i<reps;i++) {
        unsigned char *o = malloc(n);
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(ctx, o, &outlen, pts[i%reps], (int)n);
        total = outlen;
        EVP_EncryptFinal_ex(ctx, o+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
        free(o);
    }
    t1 = now();
    printf("malloc inside (demand zero): %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));
    return 0;
}
