void gcm_gmult_clmul(u64 Xi[2], const u128 Htable[16]);

/* We need the H value = AES_k(0). Use aesni_encrypt */
void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);

typedef struct { uint64_t hi, lo; } u128_local;

static double now() {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec + ts.tv_nsec*1e-9;
}

int main() {
    size_t n = 60ull*1024*1024;
    size_t blocks = n/16;
    unsigned char *pt = aligned_alloc(64, n);
    unsigned char *out = aligned_alloc(64, n);
    unsigned char keyb[16], iv[16];
    memset(pt, 1, n);
    memset(out, 0, n);
    FILE *f = fopen("/dev/urandom","rb");
    fread(keyb,1,16,f); fread(iv,1,16,f); fclose(f);
    iv[12]=iv[13]=iv[14]=iv[15]=0; /* ctr style */

    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);
    printf("rounds %d\n", key.rounds);

    int reps = 5;
    /* warmup */
    aesni_ctr32_encrypt_blocks(pt, out, blocks, &key, iv);

    double t0 = now();
    for (int i=0;i<reps;i++)
        aesni_ctr32_encrypt_blocks(pt, out, blocks, &key, iv);
    double t1 = now();
    printf("aesni_ctr32: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* ghash */
    unsigned char H[16];
    unsigned char zero[16] = {0};
    aesni_encrypt(zero, H, &key);
    /* Htable: gcm_init_clmul writes 16 u128 = 256 bytes? OpenSSL uses 16*16=256. Let's allocate more. */
    unsigned char Htable[16*16*4];
    memset(Htable, 0, sizeof Htable);
    uint64_t Xi[2] = {0,0};
    /* H is 16 bytes; gcm_init_clmul expects const u64 Xi[2] which is the H value */
    uint64_t Hxi[2];
    memcpy(Hxi, H, 16);
    gcm_init_clmul((void*)Htable, Hxi);

    memset(Xi, 0, sizeof Xi);
    gcm_ghash_clmul(Xi, (void*)Htable, pt, n);
    t0 = now();
    for (int i=0;i<reps;i++) {
        memset(Xi, 0, sizeof Xi);
        gcm_ghash_clmul(Xi, (void*)Htable, pt, n);
    }
    t1 = now();
    printf("gcm_ghash_clmul: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* both sequentially */
    t0 = now();
    for (int i=0;i<reps;i++) {
        aesni_ctr32_encrypt_blocks(pt, out, blocks, &key, iv);
        memset(Xi, 0, sizeof Xi);
        gcm_ghash_clmul(Xi, (void*)Htable, out, n);
    }
    t1 = now();
    printf("ctr+ghash seq: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));

    /* fresh buffers */
    unsigned char **pts = malloc(sizeof(void*)*reps);
    unsigned char **outs = malloc(sizeof(void*)*reps);
    for (int i=0;i<reps;i++) {
        pts[i] = aligned_alloc(64, n);
        outs[i] = aligned_alloc(64, n);
        memset(pts[i], i+1, n);
        memset(outs[i], 0, n);
    }
    t0 = now();
    for (int i=0;i<reps;i++) {
        aesni_ctr32_encrypt_blocks(pts[i], outs[i], blocks, &key, iv);
        memset(Xi, 0, sizeof Xi);
        gcm_ghash_clmul(Xi, (void*)Htable, outs[i], n);
    }
    t1 = now();
    printf("fresh ctr+ghash: %.4f s  %.1f MB/s\n", (t1-t0)/reps, reps*(n/1e6)/(t1-t0));
    return 0;
}
