{"command":"cat > gcm_test.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

void aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
void gcm_init_avx(void *Htable, const uint64_t Xi[2]);
void gcm_ghash_avx(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);
void gcm_gmult_avx(uint64_t Xi[2], const void *Htable);
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                         const void *key, unsigned char ivec[16], void *Htable);
void gcm_ghash_clmul(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);
void gcm_init_clmul(void *Htable, const uint64_t Xi[2]);

static void bswap16(unsigned char *p) {
    for (int i=0;i<8;i++) { unsigned char t=p[i]; p[i]=p[15-i]; p[15-i]=t; }
}

static void store_be64(unsigned char *p, uint64_t v) {
    for (int i=7;i>=0;i--) { p[i]=v&0xff; v>>=8; }
}

int main() {
    unsigned char keyb[16], nonce[12], aad[32];
    size_t n = 1024*1024 + 7; /* not multiple of 16 */
    unsigned char *pt = malloc(n);
    FILE *f = fopen("/dev/urandom","rb");
    fread(keyb,1,16,f); fread(nonce,1,12,f); fread(aad,1,32,f); fread(pt,1,n,f); fclose(f);

    /* reference via EVP */
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char *ref = malloc(n+16);
    int outlen=0, total=0;
    unsigned char tag[16];
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(ctx, ref, &outlen, pt, (int)n);
    total = outlen;
    EVP_EncryptFinal_ex(ctx, ref+total, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    printf("ref total %d\n", total);

    AES_KEY key;
    aesni_set_encrypt_key(keyb, 128, &key);
    unsigned char zero[16]={0}, H[16];
    aesni_encrypt(zero, H, &key);
    printf("H: "); for(int i=0;i<16;i++) printf("%02x", H[i]); printf("\n");

    unsigned char Htable[16*48];
    memset(Htable, 0, sizeof Htable);

    /* Try several H byte orders for gcm_init_avx */
    unsigned char Hvariants[3][16];
    memcpy(Hvariants[0], H, 16);
    memcpy(Hvariants[1], H, 16); bswap16(Hvariants[1]);
    /* reflected? skip */

    for (int v=0; v<2; v++) {
        memset(Htable, 0, sizeof Htable);
        uint64_t Hxi[2]; memcpy(Hxi, Hvariants[v], 16);
        gcm_init_avx(Htable, Hxi);

        /* Build J0 from nonce: GHASH(IV || pad || len) but for 12-byte nonce J0 = nonce || 0x00000001 */
        unsigned char ivec[16];
        memcpy(ivec, nonce, 12);
        ivec[12]=0; ivec[13]=0; ivec[14]=0; ivec[15]=1;
        /* counter for aesni_gcm_encrypt: it reads ivec and increments a 32-bit counter at offset 12 (big-endian, since it uses bswap via movl). 
           It does: vmovdqu (%r8), %xmm1 ; movl 0xc(%r8), %ebx
           The counter increment is done in aesni_ctr32 which bswaps. Initial counter value is the 32-bit at offset 12, interpreted little-endian by movl then bswapped to get the big-endian counter.
           If we store 0x00000001 big-endian in bytes 12..15, movl reads 0x01000000, bswap -> 1. Good.
           BUT aesni_gcm_encrypt may increment before first block or use as-is. We'll check ciphertext match.
        */
        unsigned char *ct = calloc(1, n+64);
        unsigned char ivec_copy[16]; memcpy(ivec_copy, ivec, 16);
        size_t done = aesni_gcm_encrypt(pt, ct, n, &key, ivec_copy, Htable);
        printf("variant %d processed %zu\n", v, done);

        /* remainder */
        size_t rem = n - done;
        if (rem) {
            /* encrypt one more block with counter = initial+done/16 */
            unsigned char ctr[16]; memcpy(ctr, ivec, 16);
            uint32_t c = 1 + (uint32_t)(done/16);
            ctr[12] = (c>>24)&0xff; ctr[13]=(c>>16)&0xff; ctr[14]=(c>>8)&0xff; ctr[15]=c&0xff;
            unsigned char ks[16];
            aesni_encrypt(ctr, ks, &key);
            for (size_t i=0;i<rem;i++) ct[done+i] = pt[done+i] ^ ks[i];
        }
        int ctmatch = memcmp(ct, ref, n)==0;
        printf("variant %d ct match %d\n", v, ctmatch);
        if (!ctmatch) {
            printf(" first mismatch at: ");
            for (size_t i=0;i<n;i++) if (ct[i]!=ref[i]) { printf("%zu got %02x exp %02x\n", i, ct[i], ref[i]); break; }
        }

        /* Now GHASH for tag. Xi starts 0. ghash aad, then ct, then lengths.
           Need to know byte order expected by gcm_ghash_avx. Try both. */
        for (int swap=0; swap<2; swap++) {
            uint64_t Xi[2] = {0,0};
            /* aad padded to 16 */
            unsigned char abuf[48]; memset(abuf,0,48); memcpy(abuf, aad, 32);
            unsigned char *ctpad = calloc(1, ((n+15)/16)*16);
            memcpy(ctpad, ct, n);
            size_t ct_padded = ((n+15)/16)*16;
            if (swap) {
                /* swap each 16-byte block before ghash? unlikely */
            }
            gcm_ghash_avx(Xi, Htable, abuf, 32); /* 32 is multiple of 16 */
            gcm_ghash_avx(Xi, Htable, ctpad, ct_padded);
            unsigned char lenb[16]; memset(lenb,0,16);
            uint64_t alen_bits = 32ull*8, clen_bits = (uint64_t)n*8;
            store_be64(lenb, alen_bits); store_be64(lenb+8, clen_bits);
            if (swap) bswap16(lenb); /* nonsense, skip */
            gcm_ghash_avx(Xi, Htable, lenb, 16);
            unsigned char X[16]; memcpy(X, Xi, 16);
            /* encrypt J0 and xor */
            unsigned char j0[16]; memcpy(j0, nonce, 12); j0[12]=0;j0[13]=0;j0[14]=0;j0[15]=1;
            unsigned char ek[16]; aesni_encrypt(j0, ek, &key);
            unsigned char mytag[16];
            for (int i=0;i<16;i++) mytag[i] = X[i] ^ ek[i];
            int tagmatch = memcmp(mytag, tag, 16)==0;
            if (!tagmatch) {
                /* try swapped X */
                unsigned char Xs[16]; memcpy(Xs, X, 16); bswap16(Xs);
                unsigned char mytag2[16];
                for (int i=0;i<16;i++) mytag2[i]=Xs[i]^ek[i];
                int tagmatch2 = memcmp(mytag2, tag, 16)==0;
                printf("  swap=%d tagmatch %d tagmatch_bswapX %d\n", swap, tagmatch, tagmatch2);
                printf("  mytag "); for(int i=0;i<16;i++) printf("%02x", mytag[i]); printf("\n");
                printf("  extag "); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");
                printf("  Xi    "); for(int i=0;i<16;i++) printf("%02x", X[i]); printf("\n");
            } else {
                printf("  swap=%d TAG MATCH\n", swap);
            }
            free(ctpad);
            if (swap==0 && !tagmatch) {
                /* also try gcm_gmult after feeding differently: maybe ghash expects bit-reflected blocks */
            }
        }
        free(ct);
    }
    return 0;
}
EOF
