#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

void aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
void gcm_init_avx(void *Htable, const uint64_t Xi[2]);
void gcm_init_clmul(void *Htable, const uint64_t Xi[2]);
void gcm_ghash_avx(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);
void gcm_ghash_clmul(uint64_t Xi[2], const void *Htable, const uint8_t *inp, size_t len);
void gcm_gmult_clmul(uint64_t Xi[2], const void *Htable);
void gcm_gmult_avx(uint64_t Xi[2], const void *Htable);
size_t aesni_gcm_encrypt(const unsigned char *in, unsigned char *out, size_t len,
                         const void *key, unsigned char ivec[16], void *Htable);

static void rev16(unsigned char *p){ for(int i=0;i<8;i++){unsigned char t=p[i];p[i]=p[15-i];p[15-i]=t;} }

/* bit reverse each byte */
static unsigned char brev(unsigned char b){ b=(b&0xF0)>>4|(b&0x0F)<<4; b=(b&0xCC)>>2|(b&0x33)<<2; b=(b&0xAA)>>1|(b&0x55)<<1; return b; }
static void bitrev16(unsigned char *p){ for(int i=0;i<16;i++) p[i]=brev(p[i]); }

static void store_be64(unsigned char *p, uint64_t v){ for(int i=7;i>=0;i--){p[i]=v&0xff; v>>=8;} }

int main() {
    unsigned char keyb[16]; memset(keyb, 0x11, 16);
    unsigned char nonce[12]; memset(nonce, 0x22, 12);
    unsigned char aad[16]; memset(aad, 0x33, 16);
    unsigned char pt[32]; memset(pt, 0x44, 32);

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char ref[64], tag[16]; int outlen;
    EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(ctx, NULL, NULL, keyb, nonce);
    EVP_EncryptUpdate(ctx, NULL, &outlen, aad, 16);
    EVP_EncryptUpdate(ctx, ref, &outlen, pt, 32);
    EVP_EncryptFinal_ex(ctx, ref+outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    printf("ref ct: "); for(int i=0;i<32;i++) printf("%02x", ref[i]); printf("\n");
    printf("ref tag:"); for(int i=0;i<16;i++) printf("%02x", tag[i]); printf("\n");

    AES_KEY key; aesni_set_encrypt_key(keyb, 128, &key);
    unsigned char zero[16]={0}, H[16]; aesni_encrypt(zero, H, &key);
    printf("H: "); for(int i=0;i<16;i++) printf("%02x", H[i]); printf("\n");

    /* E(J0) */
    unsigned char j0[16]; memcpy(j0, nonce, 12); j0[12]=0;j0[13]=0;j0[14]=0;j0[15]=1;
    unsigned char ek[16]; aesni_encrypt(j0, ek, &key);
    /* S = tag xor E(J0) is the GHASH output we want */
    unsigned char S[16]; for(int i=0;i<16;i++) S[i]=tag[i]^ek[i];
    printf("S expected: "); for(int i=0;i<16;i++) printf("%02x", S[i]); printf("\n");

    unsigned char data[16*3];
    memcpy(data, aad, 16);
    memcpy(data+16, ref, 32); /* ciphertext 32 bytes, but we'll test ghash of aad only first and full */

    /* length block */
    unsigned char lenb[16]; memset(lenb,0,16);
    store_be64(lenb, 16ull*8); store_be64(lenb+8, 32ull*8);

    /* variants of H and of input reflection */
    const char *names[] = {"raw", "bswap", "bitrev", "bitrev+bswap"};
    unsigned char Hv[4][16];
    memcpy(Hv[0], H, 16);
    memcpy(Hv[1], H, 16); rev16(Hv[1]);
    memcpy(Hv[2], H, 16); bitrev16(Hv[2]);
    memcpy(Hv[3], H, 16); bitrev16(Hv[3]); rev16(Hv[3]);

    for (int v=0; v<4; v++) {
        unsigned char Htable[4096]; memset(Htable,0,sizeof Htable);
        uint64_t Hxi[2]; memcpy(Hxi, Hv[v], 16);
        gcm_init_avx(Htable, Hxi);
        /* ghash aad || ct || len, try input as-is and bit-reversed blocks */
        for (int inmode=0; inmode<3; inmode++) {
            unsigned char buf[16*4];
            memcpy(buf, aad, 16);
            memcpy(buf+16, ref, 32);
            memcpy(buf+48, lenb, 16);
            if (inmode==1) { for (int b=0;b<4;b++) rev16(buf+16*b); }
            if (inmode==2) { for (int b=0;b<4;b++) bitrev16(buf+16*b); }
            uint64_t Xi[2]={0,0};
            gcm_ghash_avx(Xi, Htable, buf, 64);
            unsigned char X[16]; memcpy(X, Xi, 16);
            int match = memcmp(X, S, 16)==0;
            unsigned char Xr[16]; memcpy(Xr, X, 16); rev16(Xr);
            int matchr = memcmp(Xr, S, 16)==0;
            unsigned char Xb[16]; memcpy(Xb, X, 16); bitrev16(Xb);
            int matchb = memcmp(Xb, S, 16)==0;
            if (match || matchr || matchb)
                printf("HIT v=%s inmode=%d match=%d matchr=%d matchb=%d\n", names[v], inmode, match, matchr, matchb);
        }
    }
    printf("done scan\n");

    /* Also: maybe aesni_gcm_encrypt itself updates GHASH state if we pass Xi somehow.
       Check whether out buffer or Htable is modified to contain GHASH accumulator. */
    unsigned char Htable[4096]; memset(Htable,0,sizeof Htable);
    uint64_t Hxi[2]; memcpy(Hxi, H, 16);
    gcm_init_avx(Htable, Hxi);
    unsigned char ivec[16]; memcpy(ivec, nonce, 12); ivec[12]=0;ivec[13]=0;ivec[14]=0;ivec[15]=2;
    unsigned char out[4096]; memset(out,0,sizeof out);
    unsigned char ptl[4096]; memset(ptl, 0x44, sizeof ptl);
    /* save Htable */
    unsigned char *before = malloc(4096); memcpy(before, Htable, 4096);
    unsigned char ivec2[16]; memcpy(ivec2, ivec, 16);
    size_t done = aesni_gcm_encrypt(ptl, out, 4096, &key, ivec2, Htable);
    printf("done %zu, Htable changed? %d\n", done, memcmp(before, Htable, 4096)!=0);
    /* find first diff */
    for (int i=0;i<4096;i++) if (before[i]!=Htable[i]) { printf("first Htable diff at %d\n", i); break; }
    return 0;
}
EOF
