static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}
static size_t N;
static unsigned char *src, *dst;
static int THREADS;
static void *work(void *arg){
    long id = (long)arg;
    size_t chunk = N/THREADS;
    size_t start = id*chunk;
    size_t end = (id==THREADS-1)? N : start+chunk;
    /* read src write dst */
    memcpy(dst+start, src+start, end-start);
    return NULL;
}
int main(){
    N = 600ull*1024*1024;
    src = malloc(N); dst = malloc(N);
    memset(src, 1, N);
    int reps=3;
    for (THREADS=1; THREADS<=6; THREADS++) {
        double t0=now();
        for(int r=0;r<reps;r++){
            pthread_t th[8];
            for(long i=0;i<THREADS;i++) pthread_create(&th[i], NULL, work, (void*)i);
            for(int i=0;i<THREADS;i++) pthread_join(th[i], NULL);
        }
        double t1=now();
        double mb = reps * (N/1e6) * 2; /* read+write */
        printf("threads %d  copy throughput %.0f MB/s (read+write)  wall/rep %.4f\n", THREADS, mb/(t1-t0), (t1-t0)/reps);
    }
