{"command":"cat > mt_aes.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <pthread.h>
#include <openssl/evp.h>

static double now(){struct timespec ts; clock_gettime(CLOCK_MONOTONIC,&ts); return ts.tv_sec+ts.tv_nsec*1e-9;}

static unsigned char *PT, *OUT, KEY[16], AAD[32];
static size_t N;
static int THREADS;

typedef struct { int id; int reps; } arg_t;

static void *work(void *p){
    arg_t *a = p;
    size_t chunk = N/THREADS;
    /* align chunk to 16 */
    chunk &= ~15ull;
    size_t start = a->id * chunk;
    size_t len = (a->id==THREADS-1)? (N-start) : chunk;
    unsigned char nonce[12];
    memset(nonce, 0, 12);
    nonce[0] = a->id;
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    unsigned char tag[16];
    int outlen;
    for (int r=0;r<a->reps;r++) {
        EVP_CIPHER_CTX_reset(ctx);
        EVP_EncryptInit_ex(ctx, EVP_aes_128_gcm(), NULL, NULL, NULL);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
        EVP_EncryptInit_ex(ctx, NULL, NULL, KEY, nonce);
        EVP_EncryptUpdate(ctx, NULL, &outlen, AAD, 32);
        EVP_EncryptUpdate(ctx, OUT+start, &outlen, PT+start, (int)len);
        int total=outlen;
        EVP_EncryptFinal_ex(ctx, OUT+start+total, &outlen);
        EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);
    }
    EVP_CIPHER_CTX_free(ctx);
    return NULL;
}

int main(){
    N = 60ull*1024*1024;
    PT = malloc(N); OUT = malloc(N+64);
    FILE *f=fopen("/dev/urandom","rb"); fread(PT,1,N,f); fread(KEY,1,16,f); fclose(f);
    memset(AAD, 1, 32);
    int reps = 3;
    for (THREADS=1; THREADS<=6; THREADS++) {
        /* warmup */
        arg_t args[8];
        pthread_t th[8];
        for(int i=0;i<THREADS;i++){args[i].id=i; args[i].reps=1; pthread_create(&th[i],NULL,work,&args[i]);}
        for(int i=0;i<THREADS;i++) pthread_join(th[i],NULL);
        double t0=now();
        for(int i=0;i<THREADS;i++){args[i].id=i; args[i].reps=reps; pthread_create(&th[i],NULL,work,&args[i]);}
        for(int i=0;i<THREADS;i++) pthread_join(th[i],NULL);
        double t1=now();
        printf("threads %d  %.4f s/rep  %.0f MB/s\n", THREADS, (t1-t0)/reps, reps*(N/1e6)/(t1-t0));
    }
    return 0;
}
EOF
