#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>

/* Copy provider context? We only have the pointer. Instead: create two ctx,
   encrypt AAD on both, then on the second manually bump counter and zero Xi,
   encrypt a later chunk, and see if ciphertext matches the single-ctx encryption. */

int main(){
    unsigned char key[16], nonce[12];
    memset(key, 0x11, 16);
    for(int i=0;i<12;i++) nonce[i]=i+1;
    unsigned char aad[32]; memset(aad, 0x22, 32);
    size_t n = 4096;
    unsigned char *pt = malloc(n);
    FILE *f=fopen("/dev/urandom","rb"); fread(pt,1,n,f); fclose(f);
    unsigned char *out1 = malloc(n), *out2 = malloc(n);
    unsigned char tag1[16], tag2[16];

    EVP_CIPHER_CTX *c1 = EVP_CIPHER_CTX_new();
    int outlen, total;
    EVP_EncryptInit_ex(c1, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c1, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c1, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(c1, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(c1, out1, &outlen, pt, (int)n);
    EVP_EncryptFinal_ex(c1, out1+outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(c1, EVP_CTRL_GCM_GET_TAG, 16, tag1);

    /* second context: same init, then patch counter to skip first 1024 bytes (64 blocks)
       and encrypt pt+1024 */
    EVP_CIPHER_CTX *c2 = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(c2, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c2, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c2, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(c2, NULL, &outlen, aad, 32);

    uint64_t *q = (uint64_t*)c2;
    unsigned char *prov = (unsigned char*)q[22];
    /* counter at offset 0x100, 4 bytes, currently should be 2 */
    uint32_t ctr = *(uint32_t*)(prov+0x100);
    printf("counter before patch %u\n", ctr);
    /* skip 64 blocks */
    *(uint32_t*)(prov+0x100) = ctr + 64;
    /* zero Xi at 0x110 (16 bytes) so this chunk's ghash starts fresh */
    memset(prov+0x110, 0, 16);
    /* also len counter? at 0x138 was 0x40 = 64 after 64 bytes. Let's see current */
    printf("len field 0x130: "); for(int i=0;i<16;i++) printf("%02x", prov[0x130+i]); printf("\n");

    EVP_EncryptUpdate(c2, out2, &outlen, pt+1024, (int)(n-1024));
    printf("encrypted %d\n", outlen);
    int match = memcmp(out2, out1+1024, n-1024)==0;
    printf("chunk ct match %d\n", match);
    if (!match) {
        for (size_t i=0;i<n-1024;i++) if (out2[i]!=out1[1024+i]) {
            printf("mismatch at %zu\n", i); break;
        }
    }
    /* get tag of c2 (won't match overall, just to see it doesn't crash) */
    EVP_EncryptFinal_ex(c2, out2+outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(c2, EVP_CTRL_GCM_GET_TAG, 16, tag2);
    printf("tag2 "); for(int i=0;i<16;i++) printf("%02x", tag2[i]); printf("\n");
    printf("tag1 "); for(int i=0;i<16;i++) printf("%02x", tag1[i]); printf("\n");
    return 0;
}
