#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>

static void dump(const char *l, unsigned char *p){ printf("%s ", l); for(int i=0;i<16;i++) printf("%02x", p[i]); printf("\n"); }

/* Get Xi from a context that has encrypted exactly `len` bytes of zeros? We'll encrypt real data. */
static unsigned char *prov_of(EVP_CIPHER_CTX *c){ return (unsigned char*)((uint64_t*)c)[22]; }

int main(){
    unsigned char key[16], nonce[12];
    memset(key, 0x42, 16);
    for(int i=0;i<12;i++) nonce[i]=0x30+i;
    size_t n = 256; /* 16 blocks, no aad first */
    unsigned char pt[256];
    for (int i=0;i<256;i++) pt[i]=i;
    unsigned char out[256], tag[16];
    int outlen;

    EVP_CIPHER_CTX *full = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(full, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(full, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(full, NULL, NULL, key, nonce);
    EVP_EncryptUpdate(full, out, &outlen, pt, 256);
    /* read Xi before final */
    unsigned char Xi_full[16];
    memcpy(Xi_full, prov_of(full)+0x110, 16);
    dump("Xi after 256B", Xi_full);
    EVP_EncryptFinal_ex(full, out+outlen, &outlen);
    EVP_CIPHER_CTX_ctrl(full, EVP_CTRL_GCM_GET_TAG, 16, tag);
    dump("tag", tag);
    dump("Xi after final", prov_of(full)+0x110);

    /* chunk A: first 128 bytes, chunk B: second 128 with counter +8 */
    EVP_CIPHER_CTX *tmpl = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(tmpl, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(tmpl, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(tmpl, NULL, NULL, key, nonce);

    EVP_CIPHER_CTX *a = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *b = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_copy(a, tmpl);
    EVP_CIPHER_CTX_copy(b, tmpl);
    /* patch b counter: base 2 + 8 blocks */
    unsigned char *pb = prov_of(b);
    pb[0x107] = 2+8;
    unsigned char outa[128], outb[128];
    EVP_EncryptUpdate(a, outa, &outlen, pt, 128);
    EVP_EncryptUpdate(b, outb, &outlen, pt+128, 128);
    printf("ct match %d\n", memcmp(outa, out, 128)==0 && memcmp(outb, out+128, 128)==0);
    unsigned char XiA[16], XiB[16];
    memcpy(XiA, prov_of(a)+0x110, 16);
    memcpy(XiB, prov_of(b)+0x110, 16);
    dump("XiA", XiA);
    dump("XiB", XiB);

    /* Xi_full should be XiA * H^8 xor XiB, in GHASH field.
       We can compute XiA * H^8 by feeding 128 zero bytes to a context whose Xi is XiA.
       Easiest: take context a (Xi already XiA, counter irrelevant) and encrypt 128 zero bytes,
       the new Xi = XiA*H^8 xor GHASH(zeros) = XiA*H^8. Then xor with XiB. */
    unsigned char zeros[128]; memset(zeros, 0, 128);
    unsigned char junk[128];
    EVP_EncryptUpdate(a, junk, &outlen, zeros, 128);
    unsigned char XiA_shifted[16];
    memcpy(XiA_shifted, prov_of(a)+0x110, 16);
    dump("XiA*H^8", XiA_shifted);
    unsigned char combined[16];
    for (int i=0;i<16;i++) combined[i] = XiA_shifted[i] ^ XiB[i];
    dump("combined", combined);
    printf("combined == Xi_full? %d\n", memcmp(combined, Xi_full, 16)==0);

