    EVP_CIPHER_CTX *base = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(base, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(base, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(base, NULL, NULL, key, nonce);
    /* copy before AAD */
    EVP_CIPHER_CTX *ca = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *cb = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX_copy(ca, base);
