#include <stdio.h>
#include <string.h>
#include <openssl/evp.h>
static void dump(const char *l, unsigned char *p, int n){ printf("%s ", l); for(int i=0;i<n;i++) printf("%02x", p[i]); printf("\n"); }
static unsigned char *P(EVP_CIPHER_CTX *c){ return (unsigned char*)((uint64_t*)c)[22]; }

static void init(EVP_CIPHER_CTX *c, unsigned char *key, unsigned char *nonce){
    EVP_EncryptInit_ex(c, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
}
/* force IV materialization without consuming plaintext */
static void materialize(EVP_CIPHER_CTX *c){
    int outlen;
    EVP_EncryptUpdate(c, NULL, &outlen, (unsigned char*)"", 0);
    /* if that didn't set IV, encrypt 0 via a 0-length is a no-op. Check. */
}

int main(){
    unsigned char key[16], nonce[12];
    memset(key, 0x42, 16);
    for(int i=0;i<12;i++) nonce[i]=0x30+i;
    unsigned char pt[256]; for(int i=0;i<256;i++) pt[i]=i;
    unsigned char out[256]; int outlen;

    EVP_CIPHER_CTX *full = EVP_CIPHER_CTX_new();
    init(full, key, nonce);
    EVP_EncryptUpdate(full, out, &outlen, pt, 256);
    printf("full IV "); dump("", P(full)+0xF8, 16);
    printf("full Xi "); dump("", P(full)+0x118, 16);

    /* How to materialize IV without data? Try encrypting then we need a way to reset Xi and counter.
       Approach: encrypt 0 bytes doesn't work. Instead copy AFTER one dummy? 
       Let's just init each chunk fresh and materialize by calling EncryptUpdate of 0 after manually
       writing the IV source. Look at where nonce is stored pre-materialize. */
    EVP_CIPHER_CTX *t = EVP_CIPHER_CTX_new();
    init(t, key, nonce);
    printf("pre-materialize scan for nonce:\n");
    unsigned char *pr = P(t);
    for (int off=0; off<0x400-12; off++) {
        if (memcmp(pr+off, nonce, 12)==0) printf("  nonce at %04x\n", off);
    }
    /* Try: call a private-looking path by encrypting 16 bytes then rewinding counter and Xi.
       Rewind test: encrypt 16, save, reset counter to 2 and Xi to 0, encrypt 16 again, compare. */
    unsigned char o1[16], o2[16];
    EVP_EncryptUpdate(t, o1, &outlen, pt, 16);
    printf("after 16 IV "); dump("", P(t)+0xF8, 16);
    printf("after 16 Xi "); dump("", P(t)+0x118, 16);
    /* reset */
    P(t)[0x104]=0; P(t)[0x105]=0; P(t)[0x106]=0; P(t)[0x107]=2;
    memset(P(t)+0x118, 0, 16);
