#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>
static void dump(const char *l, unsigned char *p, int n){ printf("%s ", l); for(int i=0;i<n;i++) printf("%02x", p[i]); printf("\n"); }
static unsigned char *P(EVP_CIPHER_CTX *c){ return (unsigned char*)((uint64_t*)c)[22]; }
static void init(EVP_CIPHER_CTX *c, unsigned char *key, unsigned char *nonce){
    EVP_EncryptInit_ex(c, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
}
static void materialize_and_reset(EVP_CIPHER_CTX *c, unsigned char *pt){
    unsigned char junk[16]; int outlen;
    EVP_EncryptUpdate(c, junk, &outlen, pt, 16);
    memset(P(c)+0x118, 0, 16);
    memset(P(c)+0x138, 0, 16);
    memset(P(c)+0x130, 0, 8);
    P(c)[0x104]=0; P(c)[0x105]=0; P(c)[0x106]=0; P(c)[0x107]=2;
}
static void set_counter(EVP_CIPHER_CTX *c, uint32_t ctr){
    P(c)[0x104]=(ctr>>24)&0xff; P(c)[0x105]=(ctr>>16)&0xff;
    P(c)[0x106]=(ctr>>8)&0xff; P(c)[0x107]=ctr&0xff;
}
int main(){
    unsigned char key[16], nonce[12];
    memset(key, 0x42, 16);
    for(int i=0;i<12;i++) nonce[i]=0x30+i;
    unsigned char pt[256]; for(int i=0;i<256;i++) pt[i]=i+1;
    unsigned char out[256]; int outlen;
    EVP_CIPHER_CTX *full = EVP_CIPHER_CTX_new();
    init(full, key, nonce);
    EVP_EncryptUpdate(full, out, &outlen, pt, 256);
    printf("full Xi "); dump("", P(full)+0x138, 16);

    EVP_CIPHER_CTX *a = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *b = EVP_CIPHER_CTX_new();
    init(a, key, nonce); init(b, key, nonce);
    materialize_and_reset(a, pt);
    materialize_and_reset(b, pt);
    set_counter(b, 2+8);
    unsigned char oa[128], ob[128];
    EVP_EncryptUpdate(a, oa, &outlen, pt, 128);
    EVP_EncryptUpdate(b, ob, &outlen, pt+128, 128);
    printf("ct %d %d\n", memcmp(oa,out,128)==0, memcmp(ob,out+128,128)==0);
    printf("XiA "); dump("", P(a)+0x138, 16);
    printf("XiB "); dump("", P(b)+0x138, 16);
    unsigned char z[128], junk[128]; memset(z,0,128);
    EVP_EncryptUpdate(a, junk, &outlen, z, 128);
    printf("XiA shifted "); dump("", P(a)+0x138, 16);
    unsigned char comb[16];
    for(int i=0;i<16;i++) comb[i]=P(a)[0x138+i]^P(b)[0x138+i];
    printf("combined "); dump("", comb, 16);
    printf("ghash match %d\n", memcmp(comb, P(full)+0x138, 16)==0);

    /* tag */
    unsigned char tf[16], ts[16];
    EVP_EncryptFinal_ex(full, out, &outlen);
    EVP_CIPHER_CTX_ctrl(full, EVP_CTRL_GCM_GET_TAG, 16, tf);
    EVP_CIPHER_CTX *fin = EVP_CIPHER_CTX_new();
    init(fin, key, nonce);
    materialize_and_reset(fin, pt);
    memcpy(P(fin)+0x138, comb, 16);
    /* length = 256 */
    uint64_t len = 256;
    for(int i=7;i>=0;i--){ P(fin)[0x130+i]=len&0xff; len>>=8; }
    EVP_EncryptFinal_ex(fin, out, &outlen);
    EVP_CIPHER_CTX_ctrl(fin, EVP_CTRL_GCM_GET_TAG, 16, ts);
    printf("tag full "); dump("", tf, 16);
    printf("tag synth "); dump("", ts, 16);
    printf("tag match %d\n", memcmp(tf,ts,16)==0);

    /* with AAD */
    printf("--- aad ---\n");
    unsigned char aad[32]; memset(aad, 0x77, 32);
    EVP_CIPHER_CTX *fa = EVP_CIPHER_CTX_new();
    init(fa, key, nonce);
    EVP_EncryptUpdate(fa, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(fa, out, &outlen, pt, 256);
    unsigned char Xf[16]; memcpy(Xf, P(fa)+0x138, 16);
    EVP_CIPHER_CTX *ca = EVP_CIPHER_CTX_new();
    EVP_CIPHER_CTX *cb = EVP_CIPHER_CTX_new();
    init(ca, key, nonce); init(cb, key, nonce);
    materialize_and_reset(ca, pt); materialize_and_reset(cb, pt);
    EVP_EncryptUpdate(ca, NULL, &outlen, aad, 32); /* aad only on first */
    set_counter(cb, 2+8);
    EVP_EncryptUpdate(ca, oa, &outlen, pt, 128);
    EVP_EncryptUpdate(cb, ob, &outlen, pt+128, 128);
    printf("ct aad %d %d\n", memcmp(oa,out,128)==0, memcmp(ob,out+128,128)==0);
    memset(z,0,128);
    EVP_EncryptUpdate(ca, junk, &outlen, z, 128);
    for(int i=0;i<16;i++) comb[i]=P(ca)[0x138+i]^P(cb)[0x138+i];
    printf("ghash aad match %d\n", memcmp(comb, Xf, 16)==0);
    /* lengths: aad 32 + ct 256 */
    EVP_CIPHER_CTX *fin2 = EVP_CIPHER_CTX_new();
    init(fin2, key, nonce);
    materialize_and_reset(fin2, pt);
    memcpy(P(fin2)+0x138, comb, 16);
    /* set aad len and ct len. Where is aad len stored? */
    printf("fa len area "); dump("", P(fa)+0x128, 32);
    printf("fin2 len area "); dump("", P(fin2)+0x128, 32);
    memcpy(P(fin2)+0x128, P(fa)+0x128, 16); /* copy both length fields if adjacent */
    unsigned char tfa[16], tsa[16];
    EVP_EncryptFinal_ex(fa, out, &outlen);
    EVP_CIPHER_CTX_ctrl(fa, EVP_CTRL_GCM_GET_TAG, 16, tfa);
    EVP_EncryptFinal_ex(fin2, out, &outlen);
    EVP_CIPHER_CTX_ctrl(fin2, EVP_CTRL_GCM_GET_TAG, 16, tsa);
    printf("tag aad full "); dump("", tfa, 16);
    printf("tag aad synth "); dump("", tsa, 16);
    printf("tag aad match %d\n", memcmp(tfa, tsa, 16)==0);
    return 0;
}
