static void ghash_mul(unsigned char X[16], const unsigned char H[16]) {
    /* X = X * H in GF(2^128), GCM bit order (right shift, R = 0xe1 at top) */
    unsigned char Z[16] = {0};
    unsigned char V[16];
    memcpy(V, H, 16);
    for (int i = 0; i < 16; i++) {
        for (int bit = 7; bit >= 0; bit--) {
            if ((X[i] >> bit) & 1) {
                for (int k = 0; k < 16; k++) Z[k] ^= V[k];
            }
            int lsb = V[15] & 1;
            for (int k = 15; k > 0; k--) V[k] = (V[k] >> 1) | (V[k-1] << 7);
            V[0] >>= 1;
            if (lsb) V[0] ^= 0xe1;
        }
    }
    memcpy(X, Z, 16);
}
static void ghash_pow(unsigned char out[16], const unsigned char H[16], uint64_t n) {
    /* out = H^n */
    unsigned char base[16]; memcpy(base, H, 16);
    memset(out, 0, 16); out[15] = 1; /* one */
    while (n) {
        if (n & 1) ghash_mul(out, base);
        unsigned char tmp[16]; memcpy(tmp, base, 16);
        ghash_mul(base, tmp);
        n >>= 1;
    }
}
static unsigned char *P(EVP_CIPHER_CTX *c){ return (unsigned char*)((uint64_t*)c)[22]; }
static void init(EVP_CIPHER_CTX *c, unsigned char *key, unsigned char *nonce){
