    unsigned char junk[16]; int outlen;
    EVP_EncryptUpdate(c, junk, &outlen, scratch, 16);
    memset(P(c)+0x138,0,16); memset(P(c)+0x130,0,8);
    P(c)[0x104]=ctr>>24; P(c)[0x105]=ctr>>16; P(c)[0x106]=ctr>>8; P(c)[0x107]=ctr;
}
int main(){
    unsigned char key[16], nonce[12], aad[32];
    FILE *f=fopen("/dev/urandom","rb");
    fread(key,1,16,f); fread(nonce,1,12,f); fread(aad,1,32,f); fclose(f);
    size_t n = 10000; /* not a multiple of 16 */
    unsigned char *pt=malloc(n), *out=malloc(n);
    FILE *g=fopen("/dev/urandom","rb"); fread(pt,1,n,g); fclose(g);

    EVP_CIPHER_CTX *full=EVP_CIPHER_CTX_new(); initctx(full,key,nonce);
    int outlen;
    EVP_EncryptUpdate(full, NULL, &outlen, aad, 32);
