    unsigned char Xf[16]; memcpy(Xf, P(full)+0x138, 16);
    unsigned char tf[16];
    EVP_EncryptFinal_ex(full, out, &outlen);
    EVP_CIPHER_CTX_ctrl(full, EVP_CTRL_GCM_GET_TAG, 16, tf);

    AES_KEY ak; aesni_set_encrypt_key(key,128,&ak);
    unsigned char zero[16]={0}, H[16]; aesni_encrypt(zero,H,&ak);

    /* 3 chunks */
    int nchunks=3;
    size_t chunk = (n/nchunks) & ~15ull;
    EVP_CIPHER_CTX *cs[3];
    unsigned char *ct = malloc(n);
    unsigned char Xi[3][16];
    size_t lens[3];
    size_t off=0;
    for(int i=0;i<nchunks;i++){
        size_t len = (i==nchunks-1)? n-off : chunk;
        lens[i]=len;
        cs[i]=EVP_CIPHER_CTX_new(); initctx(cs[i], key, nonce);
        prep(cs[i], pt, 2 + (uint32_t)(off/16));
        if(i==0) EVP_EncryptUpdate(cs[i], NULL, &outlen, aad, 32);
        EVP_EncryptUpdate(cs[i], ct+off, &outlen, pt+off, (int)len);
        memcpy(Xi[i], P(cs[i])+0x138, 16);
        off += len;
    }
    printf("ct match %d\n", memcmp(ct, out, n)==0);

    /* combine: Xi[i] * H^(blocks after chunk i) */
    unsigned char acc[16]; memset(acc,0,16);
    size_t blocks_after = 0;
    for(int i=nchunks-1;i>=0;i--){
        unsigned char t[16]; memcpy(t, Xi[i], 16);
        if(blocks_after){
            unsigned char Hp[16]; gpow(Hp, H, blocks_after);
            mul(t, Hp);
        }
        for(int k=0;k<16;k++) acc[k]^=t[k];
        blocks_after += (lens[i]+15)/16;
    }
    printf("ghash match %d\n", memcmp(acc, Xf, 16)==0);

    /* tag via fin ctx */
    EVP_CIPHER_CTX *fin=EVP_CIPHER_CTX_new(); initctx(fin,key,nonce);
    prep(fin, pt, 2);
    memcpy(P(fin)+0x138, acc, 16);
    /* aad len = 32, ct len = n. Layout at 0x128 was aad len (8 bytes LE?) then ct len */
    uint64_t alen=32, clen=n;
    for(int i=7;i>=0;i--){ P(fin)[0x128+i]=alen&0xff; alen>>=8; }
    for(int i=7;i>=0;i--){ P(fin)[0x130+i]=clen&0xff; clen>>=8; }
    unsigned char ts[16];
    EVP_EncryptFinal_ex(fin, ct, &outlen);
    EVP_CIPHER_CTX_ctrl(fin, EVP_CTRL_GCM_GET_TAG, 16, ts);
    printf("tag match %d\n", memcmp(tf, ts, 16)==0);
    if(memcmp(tf,ts,16)){
        printf("tf "); for(int i=0;i<16;i++) printf("%02x", tf[i]); printf("\n");
        printf("ts "); for(int i=0;i<16;i++) printf("%02x", ts[i]); printf("\n");
        printf("full len area "); for(int i=0;i<24;i++) printf("%02x", P(full)[0x120+i]); printf("\n");
    }
    return 0;
}
