#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
void aesni_set_encrypt_key(const unsigned char *userKey, int bits, AES_KEY *key);
void aesni_encrypt(const unsigned char *in, unsigned char *out, const AES_KEY *key);
static void mul(unsigned char X[16], const unsigned char H[16]) {
    unsigned char Z[16]={0}, V[16]; memcpy(V,H,16);
    for(int i=0;i<16;i++) for(int bit=7;bit>=0;bit--){
        if((X[i]>>bit)&1) for(int k=0;k<16;k++) Z[k]^=V[k];
        int lsb=V[15]&1; for(int k=15;k>0;k--) V[k]=(V[k]>>1)|(V[k-1]<<7);
        V[0]>>=1; if(lsb) V[0]^=0xe1;
    }
    memcpy(X,Z,16);
}
static void gpow(unsigned char out[16], const unsigned char Hin[16], uint64_t n){
    unsigned char base[16]; memcpy(base, Hin, 16);
    memset(out,0,16); out[15]=1;
    while(n){ if(n&1) mul(out, base); mul(base, base); n>>=1; }
}
static unsigned char *P(EVP_CIPHER_CTX *c){ return (unsigned char*)((uint64_t*)c)[22]; }
static void initctx(EVP_CIPHER_CTX *c, unsigned char *key, unsigned char *nonce){
    EVP_EncryptInit_ex(c, EVP_aes_128_gcm(), NULL, NULL, NULL);
    EVP_CIPHER_CTX_ctrl(c, EVP_CTRL_GCM_SET_IVLEN, 12, NULL);
    EVP_EncryptInit_ex(c, NULL, NULL, key, nonce);
}
static void prep(EVP_CIPHER_CTX *c, unsigned char *scratch, uint32_t ctr){
    unsigned char junk[16]; int outlen;
    EVP_EncryptUpdate(c, junk, &outlen, scratch, 16);
    memset(P(c)+0x138,0,16); memset(P(c)+0x130,0,8); memset(P(c)+0x128,0,8);
    P(c)[0x104]=(ctr>>24)&0xff; P(c)[0x105]=(ctr>>16)&0xff;
    P(c)[0x106]=(ctr>>8)&0xff; P(c)[0x107]=ctr&0xff;
}
int main(){
    unsigned char key[16], nonce[12], aad[32];
    memset(key,0x42,16); for(int i=0;i<12;i++) nonce[i]=0x30+i; memset(aad,0x77,32);
    size_t n=200; /* 12*16=192 aligned, tail 8 */
    unsigned char pt[256], ref[256], ct[256], tag[16];
    for(int i=0;i<256;i++) pt[i]=i*3+1;
    int outlen;
    EVP_CIPHER_CTX *full=EVP_CIPHER_CTX_new(); initctx(full,key,nonce);
    EVP_EncryptUpdate(full, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(full, ref, &outlen, pt, (int)n);
    EVP_EncryptFinal_ex(full, ref, &outlen);
    EVP_CIPHER_CTX_ctrl(full, EVP_CTRL_GCM_GET_TAG, 16, tag);

    AES_KEY ak; aesni_set_encrypt_key(key,128,&ak);
    unsigned char zero[16]={0}, H[16]; aesni_encrypt(zero,H,&ak);

    /* two chunks of 96 bytes each */
    unsigned char Xi0[16], Xi1[16];
    EVP_CIPHER_CTX *c0=EVP_CIPHER_CTX_new(); initctx(c0,key,nonce); prep(c0, pt, 2);
    EVP_EncryptUpdate(c0, NULL, &outlen, aad, 32);
    EVP_EncryptUpdate(c0, ct, &outlen, pt, 96);
    memcpy(Xi0, P(c0)+0x138, 16);
    EVP_CIPHER_CTX *c1=EVP_CIPHER_CTX_new(); initctx(c1,key,nonce); prep(c1, pt, 2+6);
    EVP_EncryptUpdate(c1, ct+96, &outlen, pt+96, 96);
    memcpy(Xi1, P(c1)+0x138, 16);
    printf("ct aligned %d\n", memcmp(ct, ref, 192)==0);

    unsigned char acc[16]; memset(acc,0,16);
    unsigned char Hp[16]; gpow(Hp, H, 6); mul(acc, Hp); /* 96 bytes = 6 blocks */
    for(int k=0;k<16;k++) acc[k]^=Xi0[k];
    gpow(Hp, H, 6); mul(acc, Hp);
    for(int k=0;k<16;k++) acc[k]^=Xi1[k];

    /* expected from a natural ctx after 192 */
    EVP_CIPHER_CTX *nat=EVP_CIPHER_CTX_new(); initctx(nat,key,nonce);
    EVP_EncryptUpdate(nat, NULL, &outlen, aad, 32);
    unsigned char tmp[256];
    EVP_EncryptUpdate(nat, tmp, &outlen, pt, 192);
    printf("acc vs natural192 %d\n", memcmp(acc, P(nat)+0x138, 16)==0);
    printf("acc "); for(int i=0;i<16;i++) printf("%02x", acc[i]); printf("\n");
    printf("nat "); for(int i=0;i<16;i++) printf("%02x", P(nat)[0x138+i]); printf("\n");

    /* finish tail on nat after overwriting Xi with acc (equal) */
    memcpy(P(nat)+0x138, acc, 16);
    EVP_EncryptUpdate(nat, ct+192, &outlen, pt+192, 8);
    printf("tail ct %d\n", memcmp(ct+192, ref+192, 8)==0);
    unsigned char ts[16];
    EVP_EncryptFinal_ex(nat, ct, &outlen);
    EVP_CIPHER_CTX_ctrl(nat, EVP_CTRL_GCM_GET_TAG, 16, ts);
    printf("tag match %d\n", memcmp(ts, tag, 16)==0);
    return 0;
}
